package in.queueless.service;

import in.queueless.api.ApiModels.*;
import in.queueless.model.Domain.*;
import in.queueless.repo.*;
import java.security.SecureRandom;
import java.time.LocalDate;
import java.time.LocalTime;
import java.time.ZoneId;
import java.time.Duration;
import java.time.format.DateTimeFormatter;
import java.util.Base64;
import java.util.List;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class QueueService {
 private static final List<QueueStatus> ACTIVE=List.of(QueueStatus.WAITING,QueueStatus.SERVING);private static final SecureRandom RANDOM=new SecureRandom();private static final ZoneId INDIA=ZoneId.of("Asia/Kolkata");private static final DateTimeFormatter SLOT_FORMAT=DateTimeFormatter.ofPattern("h:mm a",java.util.Locale.ENGLISH);
 private final QueueRepository queues;private final OrganizationRepository orgs;private final ServiceRepository services;private final StaffRepository staff;private final UserRepository users;private final AppointmentMessageRepository messages;private final OrganizationService organizationService;
 public QueueService(QueueRepository q,OrganizationRepository o,ServiceRepository s,StaffRepository st,UserRepository u,AppointmentMessageRepository m,OrganizationService os){queues=q;orgs=o;services=s;staff=st;users=u;messages=m;organizationService=os;}
 @Transactional public QueueResponse join(JoinQueueRequest r){return join(r,null);}
 @Transactional public QueueResponse join(JoinQueueRequest r,String authenticatedEmail){LocalDate today=LocalDate.now(INDIA);LocalDate date=r.visitDate()==null?today:r.visitDate();if(date.isBefore(today)||date.isAfter(today.plusDays(30)))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Visit date must be within the next 30 days");ServiceItem service=services.findById(r.serviceId()).filter(x->x.active).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Service not found"));Organization org=orgs.findById(service.organization.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Organization not found"));User customer=authenticatedEmail==null?users.findByEmailIgnoreCase(r.customerEmail().trim().toLowerCase()).orElse(null):users.findByEmailIgnoreCase(authenticatedEmail).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account not found"));if(customer!=null&&customer.role!=Role.CUSTOMER)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only customer accounts can join a queue");if(customer!=null){List<QueueEntry> active=queues.findByCustomerIdAndStatusInOrderByJoinedAtDesc(customer.id,ACTIVE);if(!active.isEmpty()){QueueEntry current=active.getFirst();String message=current.status==QueueStatus.SERVING?"Your current appointment is being served. Complete it or cancel it before joining another queue.":"You already have an active appointment. Complete or cancel it before joining another queue.";throw new ResponseStatusException(HttpStatus.CONFLICT,message);}AccessPolicy.requireAccess(customer);}String email=customer==null?r.customerEmail().trim().toLowerCase():customer.email;int number=queues.findTopByOrganizationIdAndVisitDateOrderByQueueNumberDesc(org.id,date).map(x->x.queueNumber+1).orElse(1);String code=Base64.getUrlEncoder().withoutPadding().encodeToString(randomBytes(18));QueueEntry entry=queues.save(new QueueEntry(org,service,customer,r.customerName().trim(),email,code,number,date));return response(entry);}
 @Transactional(readOnly=true) public QueueResponse track(String code,String email){QueueEntry q=queues.findByTrackingCodeAndCustomerEmailIgnoreCase(code,email.trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Queue entry not found"));return response(q);}
 @Transactional(readOnly=true) public List<QueueResponse> myQueues(String email){User u=user(email);return queues.findByCustomerIdAndStatusInOrderByJoinedAtDesc(u.id,ACTIVE).stream().map(this::response).toList();}
 @Transactional(readOnly=true) public List<QueueResponse> myHistory(String email){User u=user(email);return queues.findByCustomerIdOrderByJoinedAtDesc(u.id).stream().filter(q->q.status==QueueStatus.COMPLETED||q.status==QueueStatus.CANCELLED||q.status==QueueStatus.NO_SHOW).map(this::response).toList();}
 @Transactional(readOnly=true) public List<QueueResponse> ownerHistory(Long orgId,String email){organizationService.owned(orgId,email);return queues.findByOrganizationIdOrderByJoinedAtDesc(orgId).stream().filter(q->q.status==QueueStatus.COMPLETED||q.status==QueueStatus.CANCELLED||q.status==QueueStatus.NO_SHOW).map(this::response).toList();}
 @Transactional public QueueResponse cancelByCustomer(Long id,String reason,String email){User u=user(email);QueueEntry q=queues.findByIdAndCustomerId(id,u.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));return cancel(q,reason);}
 @Transactional public QueueResponse cancelByCode(String code,String email,String reason){QueueEntry q=queues.findByTrackingCodeAndCustomerEmailIgnoreCase(code,email.trim()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Queue entry not found"));return cancel(q,reason);}
 private QueueResponse cancel(QueueEntry q,String reason){if(q.status!=QueueStatus.WAITING&&q.status!=QueueStatus.SERVING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only active appointments can be cancelled");q.status=QueueStatus.CANCELLED;q.cancellationReason=reason.trim();return response(q);}
 @Transactional public QueueResponse cancelByOwner(Long orgId,Long id,String email){organizationService.owned(orgId,email);QueueEntry q=queues.findByIdAndOrganizationId(id,orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Queue entry not found"));return cancel(q,"Cancelled by organization");}
 @Transactional(readOnly=true) public List<QueueResponse> live(Long orgId,LocalDate date,String email){organizationService.owned(orgId,email);return queues.findByOrganizationIdAndVisitDateOrderByQueueNumberAsc(orgId,date).stream().map(this::response).toList();}
 @Transactional public QueueResponse update(Long orgId,Long id,QueueStatus target,String email){organizationService.owned(orgId,email);QueueEntry q=queues.findByIdAndOrganizationId(id,orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Queue entry not found"));if(target==QueueStatus.SERVING){if(q.status!=QueueStatus.WAITING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only waiting entries can be called");q.status=target;q.startedAt=java.time.Instant.now();}else if(target==QueueStatus.COMPLETED){if(q.status!=QueueStatus.SERVING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only a serving entry can be completed");q.status=target;q.completedAt=java.time.Instant.now();}else if(target==QueueStatus.NO_SHOW){if(q.status!=QueueStatus.WAITING)throw new ResponseStatusException(HttpStatus.CONFLICT,"Only waiting entries can be marked no-show");q.status=target;}else throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported queue status change");return response(q);}
 @Transactional public QueueResponse assign(Long orgId,Long id,Long staffId,String email){organizationService.owned(orgId,email);QueueEntry q=queues.findByIdAndOrganizationId(id,orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Queue entry not found"));q.staff=staff.findByIdAndOrganization_IdAndActiveTrue(staffId,orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Staff member not found"));return response(q);}
 @Transactional public List<AppointmentMessageResponse> messagesForCustomer(Long id,String email){User u=user(email);QueueEntry q=queues.findByIdAndCustomerId(id,u.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));return messageList(q);}
 @Transactional public List<AppointmentMessageResponse> messagesForOwner(Long orgId,Long id,String email){organizationService.owned(orgId,email);QueueEntry q=queues.findByIdAndOrganizationId(id,orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));return messageList(q);}
 @Transactional public AppointmentMessageResponse sendCustomerMessage(Long id,String body,String email){User u=user(email);QueueEntry q=queues.findByIdAndCustomerId(id,u.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));return saveMessage(q,u,body);}
 @Transactional public AppointmentMessageResponse sendOwnerMessage(Long orgId,Long id,String body,String email){organizationService.owned(orgId,email);QueueEntry q=queues.findByIdAndOrganizationId(id,orgId).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));return saveMessage(q,user(email),body);}
 @Transactional public QueueResponse review(Long id,int rating,String comment,String email){User u=user(email);QueueEntry q=queues.findByIdAndCustomerId(id,u.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Appointment not found"));if(q.status!=QueueStatus.COMPLETED)throw new ResponseStatusException(HttpStatus.CONFLICT,"You can rate a visit after the organization marks it complete");if(q.rating!=null)throw new ResponseStatusException(HttpStatus.CONFLICT,"You have already rated this visit");q.rating=rating;q.reviewComment=comment==null?null:comment.trim();return response(q);}
 @Transactional(readOnly=true) public RatingSummary ratings(Long orgId){organizationService.get(orgId,null);var reviews=queues.findByOrganizationIdOrderByJoinedAtDesc(orgId).stream().filter(q->q.rating!=null).map(q->new ReviewResponse(q.id,publicReviewerName(q.customerName),q.rating,q.reviewComment,q.completedAt)).toList();double average=reviews.isEmpty()?0:reviews.stream().mapToInt(ReviewResponse::rating).average().orElse(0);return new RatingSummary(Math.round(average*10.0)/10.0,reviews.size(),reviews);}
 private String publicReviewerName(String name){String[] parts=name.trim().split("\\s+");return parts.length>1?parts[0]+" "+parts[parts.length-1].charAt(0)+".":parts[0];}
 private List<AppointmentMessageResponse> messageList(QueueEntry q){ensureChatOpen(q);return messages.findByQueueEntryIdOrderByCreatedAtAsc(q.id).stream().map(m->new AppointmentMessageResponse(m.id,m.author.name,m.author.role.name(),m.body,m.createdAt)).toList();}
 private AppointmentMessageResponse saveMessage(QueueEntry q,User author,String body){ensureChatOpen(q);String text=body.trim();if(text.isEmpty())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Message cannot be empty");var m=messages.save(new AppointmentMessage(q,author,text));return new AppointmentMessageResponse(m.id,author.name,author.role.name(),m.body,m.createdAt);}
 private void ensureChatOpen(QueueEntry q){if(q.status==QueueStatus.CANCELLED||q.status==QueueStatus.COMPLETED||q.status==QueueStatus.NO_SHOW)throw new ResponseStatusException(HttpStatus.CONFLICT,"Messaging is closed for this appointment");}
 private QueueResponse response(QueueEntry q){List<QueueEntry> earlier=queues.findByOrganizationIdAndVisitDateOrderByQueueNumberAsc(q.organization.id,q.visitDate).stream().filter(x->x.queueNumber<q.queueNumber).toList();int ahead=0,wait=0;for(QueueEntry previous:earlier){if(previous.status==QueueStatus.WAITING){ahead++;wait+=previous.service.durationMinutes;}else if(previous.status==QueueStatus.SERVING){ahead++;wait+=remainingMinutes(previous);}}LocalTime tenAm=LocalTime.of(10,0);LocalTime start=q.visitDate.equals(LocalDate.now(INDIA))&&LocalTime.now(INDIA).isAfter(tenAm)?LocalTime.now(INDIA).withSecond(0).withNano(0):tenAm;LocalTime estimated=q.status==QueueStatus.SERVING&&q.startedAt!=null?q.startedAt.atZone(INDIA).toLocalTime():start.plusMinutes(wait);return new QueueResponse(q.id,q.organization.id,q.organization.name,q.organization.category,q.organization.address,q.organization.city,q.trackingCode,q.queueNumber,q.status.name(),q.customerName,q.customerEmail,q.visitDate,q.joinedAt,q.service.id,q.service.name,ahead,wait,estimated.format(SLOT_FORMAT),q.staff==null?null:q.staff.id,q.staff==null?null:q.staff.name,q.startedAt,q.completedAt,q.cancellationReason,q.rating,q.reviewComment);}
 private int remainingMinutes(QueueEntry q){if(q.startedAt==null)return q.service.durationMinutes;long elapsed=Duration.between(q.startedAt,java.time.Instant.now()).toMinutes();return (int)Math.max(0,q.service.durationMinutes-elapsed);}
 private Long serviceOrgId(Long id){return services.findById(id).map(x->x.organization.id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Service not found"));}
 private User user(String email){return users.findByEmailIgnoreCase(email).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Account not found"));}
 private byte[] randomBytes(int n){byte[] b=new byte[n];RANDOM.nextBytes(b);return b;}
}
